assignments.value:
={{ (() => {
  const r = $json.body?.reference ?? {};
  const paths = {
    'Site': `companies/${r.companyID}/sites/${r.siteID}`,
    'Company customer': `companies/0/customers/companies/${r.customerID}`,
    'Contact': `companies/0/contacts/${r.contactID}`,
    'Quote': `companies/${r.companyID}/quotes/${r.quoteID}`,
    'Job': `companies/${r.companyID}/jobs/${r.jobID}`,
  };
  return paths[$json.body?.name] ?? '';
})() }}

parameters.jsonOutput:
={{ (() => {
  const rec = $('Get Simpro Record').first().json;
  const cfg = $('Workflow Config').first().json;
  const event = $('When Executed by Another Workflow').first().json;
  // Site / Quote / Job use Name, company customers use CompanyName, contacts use GivenName + FamilyName.
  const recordName = String(rec.Name ?? rec.CompanyName ?? [rec.GivenName, rec.FamilyName].filter(Boolean).join(' ')).trim();
  if (event.body?.name === 'Contact') {
    // Contacts: test record = email domain is one of contactEmailDomains (exact match, not case-sensitive).
    const email = String(rec.Email ?? '').trim().toLowerCase();
    const domain = email.includes('@') ? email.split('@').pop() : '';
    const domains = String(cfg.contactEmailDomains).split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
    return { ...event, recordName, email, isTestRecord: domains.includes(domain) };
  }
  return { ...event, recordName, isTestRecord: recordName.startsWith(cfg.namePrefix) };
})() }}
